MC.registerPack({"id":"trors","cards":[{"id":"04001a","name":"호크아이","en":"* Hawkeye","type":"hero","enc":false,"unique":true,"hp":9,"atk":2,"thw":1,"def":1,"hs":5,"tr":["AVENGER"],"traits":["어벤저"],"text":"\"신속한 활시위 당기기\" — <b>행동</b>: 호크아이를 소진 → 호크아이 활을 준비."},{"id":"04001b","name":"클린트 바튼","en":"* Clint Barton","type":"alter","enc":false,"unique":true,"hp":9,"rec":3,"hs":6,"tr":["S.H.I.E.L.D"],"traits":["S.H.I.E.L.D"],"text":"전용 무기 — <b>행동</b>: 아무 유형의 자원을 1개 소모 → 당신의 덱과 버린 더미에서 호크아이 활을 찾아 당신의 손에 더합니다. 당신의 덱을 섞습니다(페이즈마다 1회 제한)."},{"id":"04002","name":"호크아이 활","en":"* Hawkeye's Bow","type":"upgrade","enc":false,"unique":true,"cost":0,"res":"G","cls":"Hero","tr":["WEAPON"],"restricted":1,"traits":["무기"],"text":"한정.\n당신의 히어로가 공격 +1을 받고 당신의 각 [[화살]] 공격은 원거리를 얻습니다."},{"id":"04003","name":"호크아이 화살통","en":"* Hawkeye's Quiver","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"B","cls":"Hero","tr":["ITEM"],"traits":["도구"],"text":"당신은 이 카드에 장착된 [[화살]] 이벤트를 당신의 손에 있는 것처럼 플레이해도 됩니다.\n<b>히어로 행동</b>: 호크아이 화살통을 소진 → 당신의 덱 맨 위 5장에서 [[화살]] 이벤트 1장을 찾아 이 카드에 앞면으로 장착합니다."},{"id":"04004","name":"모킹버드","en":"* Mockingbird","type":"ally","enc":false,"sub":"바비 모스","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":3,"res":"G","cls":"Hero","tr":["AVENGER","S.H.I.E.L.D"],"traits":["어벤저","S.H.I.E.L.D"],"text":"<b>난입</b>: 빌런이 당신에게 공격을 개시할 때, 아무 유형의 자원을 1개 소모하고 모킹버드를 당신의 손으로 되돌림 → 이 공격에서 모든 피해를 방지."},{"id":"04005","name":"음파 화살","en":"Sonic Arrow","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["ARROW","ATTACK"],"traits":["화살","공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 호크아이 활을 소진 → 적 하나를 혼란에 빠뜨리고 피해 3점을 입힘(이미 혼란에 빠졌다면 대신 피해 5점을 입힘)."},{"id":"04006","name":"폭파 화살","en":"Explosive Arrow","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["ARROW"],"traits":["화살"],"text":"<b>히어로 행동</b>: 호크아이 활을 소진하고 플레이어 하나를 선택 → 선택한 플레이어와 교전 중인 각 하수인과 빌런에게 피해 3점을 입힘."},{"id":"04007","name":"전류 화살","en":"Electric Arrow","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["ARROW","ATTACK"],"traits":["화살","공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 호크아이 활 소진 → 적 하나를 기절시키고 피해 3점을 입힘(이미 기절했다면 대신 피해 5점을 입힘)."},{"id":"04008","name":"케이블 화살","en":"Cable Arrow","type":"event","enc":false,"unique":false,"cost":1,"res":"R","cls":"Hero","tr":["ARROW","THWART"],"traits":["화살","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 호크아이 활 소진 → 플레이 영역에 있는 모든 위기 아이콘을 무시한 채로 음모 하나에서 위협을 3만큼 제거."},{"id":"04009","name":"비브라늄 화살","en":"Vibranium Arrow","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero","tr":["ARROW","ATTACK"],"traits":["화살","공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 호크아이 활 소진 → 적 하나에게 피해 6점을 입힘. 이 공격은 관통을 얻음."},{"id":"04010","name":"숙련된 명사수","en":"Expert Marksman","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"G","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"<b>자원</b>: 숙련된 명사수를 소진 → [[화살]] 이벤트를 플레이할 때만 소모할 수 있는 [wild] 자원 생성."},{"id":"04011","name":"호크아이","en":"* Hawkeye","type":"ally","enc":false,"sub":"케이트 비숍","unique":true,"hp":2,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"R","cls":"Leadership","tr":["AVENGER"],"traits":["어벤저"],"text":"<b>행동</b>: 이 동료를 소진하고 당신의 손에서 카드 1장을 버림 → 적 하나에게 피해 X점을 입힘. X는 버려진 카드에 인쇄된 자원 비용."},{"id":"04012","name":"블랙 나이트","en":"* Black Knight","type":"ally","enc":false,"sub":"데인 휘트먼","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"R","cls":"Leadership","tr":["AVENGER"],"traits":["어벤저"],"text":"[star] 블랙 나이트의 기본 공격은 관통을 얻습니다.","star":true},{"id":"04013","name":"골리앗","en":"* Goliath","type":"ally","enc":false,"sub":"빌 포스터","unique":true,"hp":4,"atk":1,"atkStar":true,"atkCons":2,"thw":2,"thwStar":true,"cost":4,"res":"B","cls":"Leadership","tr":["AVENGER"],"traits":["어벤저"],"text":"<b>행동</b>: 골리앗은 페이즈의 끝까지 공격 +4를 받습니다. 페이즈의 끝에, 골리앗을 버립니다(페이즈마다 최대 1번)."},{"id":"04014","name":"U.S. 에이전트","en":"* U.S. Agent","type":"ally","enc":false,"sub":"존 워커","unique":true,"hp":5,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Leadership","retaliate":1,"tr":["AVENGER"],"traits":["어벤저"],"text":"반격 1."},{"id":"04015","name":"스카이 사이클","en":"Sky Cycle","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Leadership","tr":["VEHICLE"],"maxPer":1,"traits":["탈것"],"text":"[[어벤저]] 동료에게 장착합니다. 동료마다 1장 제한.\n장착된 동료는 [[공중]] 특성을 얻습니다.\n<b>행동</b>: 스카이 사이클을 소진 → 장착된 동료를 준비."},{"id":"04016","name":"팀 훈련","en":"Team Training","type":"support","enc":false,"unique":false,"cost":2,"res":"R","cls":"Leadership","tr":["CONDITION"],"maxPer":1,"traits":["상태"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신이 조종하는 각 동료는 생명력 +1을 받습니다."},{"id":"04017","name":"활동 준비 완료","en":"Ready for Action","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Leadership","tr":["TACTIC"],"traits":["전술"],"text":"<b>히어로 행동</b>: 당신이 조종하는 동료 하나에게 강인함 상태 카드를 줍니다."},{"id":"04018","name":"진두지휘","en":"Lead from the Front","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Leadership","tr":["TACTIC"],"traits":["전술"],"text":"<b>히어로 행동</b>: 플레이어 하나를 선택합니다. 그 플레이어가 조종하는 모든 캐릭터는 페이즈의 끝까지 저지 +1과 공격 +1을 받습니다.","link":"01070"},{"id":"04019","name":"통솔의 힘","en":"The Power of Leadership","type":"resource","enc":false,"unique":false,"res":"G","cls":"Leadership","tr":[],"maxDeck":2,"traits":[],"text":"덱마다 최대 2장.\n 통솔<i>(파란색)</i> 카드에 이 카드를 비용으로 지불하는 한, 이 카드가 생성하는 자원은 2배가 됩니다.","link":"01072"},{"id":"04020","name":"워머신","en":"* War Machine","type":"ally","enc":false,"sub":"제임스 로즈","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"B","cls":"Basic","tr":["AVENGER","S.H.I.E.L.D"],"toughness":1,"traits":["어벤저","S.H.I.E.L.D"],"text":"강인.\n[star] 워머신의 기본 공격은 원거리를 얻습니다.","star":true},{"id":"04021","name":"어벤져스 타워","en":"* Avengers Tower","type":"support","enc":false,"unique":true,"cost":2,"res":"B","cls":"Basic","tr":["AVENGER","LOCATION"],"traits":["어벤저","장소"],"text":"당신이 조종하는 모든 동료에게 [[어벤저]] 특성이 있다면, 당신의 동료 제한을 1만큼 증가시킵니다.\n<b>행동:</b> 어벤져스 타워를 소진 → 플레이어가 이번 페이즈에 플레이하는 다음 [[어벤저]] 동료의 자원 비용을 1만큼 감소시킴.","link":"03024"},{"id":"04022","name":"지구의 위대한 영웅들","en":"Earth's Mightiest Heroes","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Basic","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 당신이 조종하는 [[어벤저]] 캐릭터 하나를 소진 → 당신이 조종하는 다른 [[어벤저]] 캐릭터 하나를 준비."},{"id":"04023","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"04024","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"04025","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"04026","name":"범죄 이력","en":"Criminal Past","type":"obligation","enc":true,"set":"Hawkeye","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>클린트 바튼 플레이어에게 이 카드를 줍니다.</i></b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 클린트 바튼을 소진 → 이 카드를 게임에서 제거.\n• 플레이 영역에서 호크아이 활을 버립니다. 이 의무 카드를 버립니다.\n"},{"id":"04027","name":"크로스파이어","en":"* Crossfire","type":"minion","enc":true,"set":"Hawkeye Nemesis","unique":true,"hp":4,"atk":2,"sch":1,"tr":["MERCENARY"],"quickstrike":1,"nemesis":true,"traits":["용병"],"text":"속공.\n크로스파이어의 공격은 관통을 얻습니다.\n<hr />\n[star] <b>강화</b>: 이 강화 능력이 공격 중에 해결되면, 이 공격은 관통을 얻습니다.","star":true,"boostStar":true},{"id":"04028","name":"죽음의 표식","en":"Marked for Death","type":"side","enc":true,"set":"Hawkeye Nemesis","unique":false,"boost":3,"start":5,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때:</b> 클린트 바튼플레이어는 자신의 손, 덱, 버린 더미, 플레이 영역에서 모킹버드를 찾아 앞면으로 이 카드 밑에 놓습니다. 이 음모가 격파될 때, 모킹버드를 소유자의 손으로 되돌립니다."},{"id":"04029","name":"크로스파이어 라이플","en":"* Crossfire's Rifle","type":"attachment","enc":true,"set":"Hawkeye Nemesis","unique":true,"boost":2,"plus":{"atk":2},"tr":["WEAPON"],"traits":["무기"],"text":"크로스파이어에게 장착합니다. 그럴 수 없다면, 빌런에게 장착합니다.\n[star] 장착된 적이 공격할 때, 이 공격은 원거리를 얻습니다.\n<b>히어로 행동:</b> 당신의 히어로를 소진하고 [wild] 자원을 소모 → 크로스파이어 라이플을 버림","star":true},{"id":"04030","name":"저격수의 한 발","en":"Sniper Shot","type":"treachery","enc":true,"set":"Hawkeye Nemesis","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상):</b> 주요 음모에 위협을 3만큼 놓습니다.\n<b>공개될 때(히어로):</b> 당신의 히어로가 피해 3점을 입습니다."},{"id":"04031a","name":"스파이더우먼","en":"* Spider-Woman","type":"hero","enc":false,"unique":true,"hp":11,"atk":1,"thw":1,"def":1,"hs":5,"tr":["AVENGER","SPY"],"traits":["어벤저","첩보원"],"text":"\"슈퍼휴먼의 민첩성\" — <b>난입</b>: 당신이 성향 카드를 플레이할 때, 스파이더우먼은 라운드 끝까지 저지 +1, 공격 +1, 방어 +1을 받습니다(각 성향에 대해 라운드마다 1회 제한)."},{"id":"04031b","name":"제시카 드류","en":"* Jessica Drew","type":"alter","enc":false,"unique":true,"hp":11,"rec":3,"hs":6,"tr":["S.H.I.E.L.D","SPY"],"traits":["S.H.I.E.L.D","첩보원"],"text":"이중 첩자 — 나만의 덱 구성 과정 중 '정확히 하나의 성향'을 선택하는 대신 '두 개의 성향'을 선택합니다. 당신의 덱에 해당 성향들의 카드는 정확히 같은 수만큼 존재해야 합니다.\n<b>행동</b>: 아무 덱 맨 위에서 카드 1장을 봅니다(라운드마다 1회 제한.)"},{"id":"04032","name":"캡틴 마블","en":"* Captain Marvel","type":"ally","enc":false,"sub":"캐럴 댄버스","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":4,"res":"G","cls":"Hero","tr":["AVENGER"],"traits":["어벤저"],"text":"<b>반응</b>: 캡틴 마블이 기본 기능을 사용한 후, 카드 1장을 뽑습니다."},{"id":"04033","name":"능숙한 움직임","en":"Finesse","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["CONDITION"],"traits":["상태"],"text":"<b>히어로 자원</b>: 능숙한 움직임을 소진 → 성향 카드를 플레이할 때만 소모할 수 있는 [wild] 자원을 생성."},{"id":"04034","name":"제시카 드류의 아파트","en":"* Jessica Drew's Apartment","type":"support","enc":false,"unique":true,"cost":1,"res":"R","cls":"Hero","tr":["LOCATION"],"traits":["장소"],"text":"<b>일상 행동</b>: 제시카 드류의 집을 소진 → 당신의 덱 맨 위 5장에서 성향 카드 1장을 찾아 당신의 손에 더합니다. 당신의 덱을 섞습니다."},{"id":"04035","name":"베놈 블래스트","en":"Venom Blast","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero;Aggression","tr":["ATTACK","SUPERPOWER"],"traits":["공격","슈퍼파워"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 5점을 입힙니다."},{"id":"04036","name":"페로몬","en":"Pheromones","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Hero;Leadership","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 행동</b>: 적 하나를 기절시키고 혼란에 빠뜨립니다."},{"id":"04037","name":"오염물질 면역","en":"Contaminant Immunity","type":"event","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Hero;Protection","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 행동</b>: 스파이더우먼이 입은 피해 3점을 치료하고 강인함 상태 카드를 줍니다."},{"id":"04038","name":"눈에 띄지 않게","en":"Inconspicuous","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Hero;Justice","tr":["SKILL","THWART"],"traits":["기술","저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 플레이 영역에 있는 음모에서 원하는 조합으로 위협을 총 3만큼 제거합니다."},{"id":"04039","name":"자가추진 글라이더","en":"Self-Propelled Glide","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["SUPERPOWER"],"traits":["슈퍼파워"],"text":"<b>히어로 행동</b>: 스파이더우먼을 준비합니다. 스파이더우먼은 라운드 끝까지 [[공중]] 특성을 얻습니다."},{"id":"04040","name":"스파이더걸","en":"* Spider-Girl","type":"ally","enc":false,"sub":"아냐 코라존","unique":true,"hp":2,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":2,"res":"Y","cls":"Aggression","tr":["AVENGER"],"traits":["어벤저"],"text":"<b>반응</b>: 당신의 손에서 스파이더걸을 플레이한 후, 하수인 하나를 기절시키고 혼란에 빠뜨립니다."},{"id":"04041","name":"격투 훈련","en":"Combat Training","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"R","cls":"Aggression","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신의 히어로가 공격 +1을 받습니다.","link":"01057"},{"id":"04042","name":"전술공격팀","en":"Tac Team","type":"support","enc":false,"unique":false,"cost":3,"res":"Y","cls":"Aggression","tr":["S.H.I.E.L.D"],"uses":{"n":3,"kind":"attack"},"traits":["S.H.I.E.L.D"],"text":"사용(공격 카운터 3). <i>(카운터를 3만큼 놓은 채로 플레이 영역에 들어옵니다. 카운터가 모두 사라지면 이 카드를 버립니다)</i>\n<b>행동</b>: 전술공격팀을 소진하고 이 카드에서 공격 카운터를 1만큼 제거 → 적 하나에게 피해 2점을 입힘.","link":"01056"},{"id":"04043","name":"이점을 활용하다","en":"Press the Advantage","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 2점을 입힙니다. 그 적이 기절했거나 혼란에 빠졌다면, 카드 1장을 뽑습니다."},{"id":"04044","name":"관통 타격","en":"Piercing Strike","type":"event","enc":false,"unique":false,"cost":2,"res":"R","cls":"Aggression","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 3점을 입힙니다. 이 공격은 관통을 얻습니다."},{"id":"04045","name":"스파이더맨","en":"* Spider-Man","type":"ally","enc":false,"sub":"피터 파커","unique":true,"hp":4,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":5,"res":"B","cls":"Justice","tr":["AVENGER"],"traits":["어벤저"],"text":"<b>반응</b>: 당신의 손에서 스파이더맨을 플레이한 후, 부가 음모 하나에서 위협을 3 [per_hero]만큼 제거합니다."},{"id":"04046","name":"히어로의 직감","en":"Heroic Intuition","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"Y","cls":"Justice","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n당신의 히어로가 저지 +1을 받습니다.","link":"01065"},{"id":"04047","name":"능숙한 조사자","en":"Skilled Investigator","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"R","cls":"Justice","tr":["SKILL"],"maxPer":1,"traits":["기술"],"text":"이 카드를 플레이하면, 조종할 플레이어를 정합니다. 플레이어마다 최대 1장.\n<b>히어로 반응</b>: 부가 음모가 격파된 후, 능숙한 조사자를 소진 → 카드 1장을 뽑음."},{"id":"04048","name":"심문실","en":"Interrogation Room","type":"support","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":["LOCATION"],"maxPer":1,"traits":["장소"],"text":"플레이어마다 최대 1장.\n<b>반응</b>: 당신이 하수인 하나를 격파한 후, 심문실을 소진 → 음모 하나에서 위협을 1만큼 제거합니다.","link":"01063"},{"id":"04049","name":"지역 시민 구출","en":"Clear the Area","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Justice","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 2만큼 제거합니다. 이렇게 그 음모의 마지막 위협을 제거하면, 카드 1장을 뽑습니다."},{"id":"04050","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"04051","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"04052","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"04053","name":"변동하는 충성심","en":"Uncertain Loyalties","type":"obligation","enc":true,"set":"Spider-Woman","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>제시카 드류 플레이어에게 이 카드를 줍니다.</i></b>\n• 제시카 드류를 소진 → 변동하는 충성심을 게임에서 제거.\n• 주요 음모에 위협을 3만큼 놓습니다. 이 의무 카드를 버립니다.\n"},{"id":"04054","name":"바이퍼","en":"* The Viper","type":"minion","enc":true,"set":"Spider-Woman Nemesis","unique":true,"hp":5,"atk":2,"sch":2,"boost":3,"tr":["ELITE","HYDRA"],"nemesis":true,"traits":["간부","하이드라"],"text":"바이퍼가 당신과 교전 중인 동안, 당신의 손 크기가 1만큼 감소합니다.\n(스파이더우먼의 숙적 하수인.)"},{"id":"04055","name":"바이퍼의 야망","en":"The Viper's Ambition","type":"side","enc":true,"set":"Spider-Woman Nemesis","unique":false,"boost":2,"start":2,"hazard":1,"tr":[],"traits":[],"text":"<b>공개될 때:</b> 이 카드에 위협을 1 [per_hero] 만큼 추가로 놓습니다."},{"id":"04056","name":"하이드라 직업군인","en":"Hydra Regular","type":"minion","enc":true,"set":"Spider-Woman Nemesis","unique":false,"hp":2,"atk":2,"sch":1,"boost":2,"tr":["HYDRA"],"incite":1,"traits":["하이드라"],"text":"진척 1<i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다).</i>."},{"id":"04057","name":"헤일 하이드라!","en":"Hail Hydra!","type":"treachery","enc":true,"set":"Captain America Nemesis","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 [[하이드라]] 하수인이 교전 중인 히어로를 공격합니다. 이렇게 공격받지 않은 각 플레이어는 조우 덱과 버린 조우 더미에서 [[하이드라]] 하수인 하나를 찾아 그 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 찾았다면, 조우 덱을 섞습니다.","link":"03030"},{"id":"04058","name":"크로스본즈","en":"* Crossbones","type":"villain","enc":true,"set":"Crossbones","unique":true,"hp":12,"hpStar":true,"atk":1,"sch":1,"stage":1,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"[star] 크로스본즈가 [[무기]] 장착 카드를 가지고 있는 동안, 그의 공격은 관통을 얻습니다. <i>(피해를 입히기 전에 대상에게서 강인함 상태 카드를 모두 버립니다.)</i>","star":true},{"id":"04059","name":"크로스본즈","en":"* Crossbones","type":"villain","enc":true,"set":"Crossbones","unique":true,"hp":14,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"[star] 크로스본즈가 [[무기]] 장착 카드를 가지고 있는 동안, 그의 공격은 관통을 얻습니다.\n<b>공개될 때</b>: 조우 덱과 버린 조우 더미에서 크로스본즈 기관총을 찾아 크로스본즈에게 장착합니다. 조우 덱을 섞습니다.","star":true},{"id":"04060","name":"크로스본즈","en":"* Crossbones","type":"villain","enc":true,"set":"Crossbones","unique":true,"hp":16,"hpStar":true,"atk":3,"sch":2,"stage":3,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"[star] 크로스본즈가 [[무기]] 장착 카드를 가지고 있는 동안, 그의 공격은 관통을 얻습니다.\n<b>공개될 때</b>: 실험 무기 덱 맨 위 카드를 공개합니다.","star":true},{"id":"04061a","name":"아테나 산 습격","en":"Attack on Mount Athena","type":"main","enc":true,"set":"Crossbones","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 크로스본즈 (I), 크로스본즈 (II). 크로스본즈, 실험 무기, 일반 조우 세트. 모듈식 세트 3개 <i>(하이드라 맹공, 무기의 달인, 하이드라 군단).</i>\n<b>사전 준비</b>: 실험 무기 덱을 만들어 주요 음모 덱 옆에 놓습니다. <i>(규칙서 5쪽 참조.)</i>"},{"id":"04061b","name":"아테나 산 습격","en":"Attack on Mount Athena","type":"main","enc":true,"set":"Crossbones","unique":false,"start":0,"target":3,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 실험 무기 덱 맨 위 카드를 공개합니다."},{"id":"04062a","name":"인피니티 스톤","en":"The Infinity Stone","type":"main","enc":true,"set":"Crossbones","unique":false,"stage":2,"tr":[],"traits":[]},{"id":"04062b","name":"인피니티 스톤","en":"The Infinity Stone","type":"main","enc":true,"set":"Crossbones","unique":false,"start":1,"startStar":true,"target":6,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 실험 무기 덱 맨 위 카드를 공개합니다."},{"id":"04063a","name":"도주","en":"The Getaway","type":"main","enc":true,"set":"Crossbones","unique":false,"stage":3,"tr":[],"traits":[]},{"id":"04063b","name":"도주","en":"The Getaway","type":"main","enc":true,"set":"Crossbones","unique":false,"start":1,"startStar":true,"target":5,"targetStar":true,"esc":1,"escStar":true,"stage":3,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 실험 무기 덱 맨 위 카드를 공개합니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>"},{"id":"04064","name":"크로스본즈 기관총","en":"* Crossbones' Machine Gun","type":"attachment","enc":true,"set":"Crossbones","unique":true,"boost":3,"plus":{"atk":0},"tr":["WEAPON"],"uses":{"n":2,"kind":"ammo","star":true},"traits":["무기"],"text":"크로스본즈에게 장착합니다. 사용(탄약 카운터 2[per_hero]).\n[star] <b>강제 난입</b>: 크로스본즈가 당신을 공격할 때, 이 카드에서 탄약 카운터를 1만큼 제거하고 조우 덱 맨 위 카드를 버림 → 버려진 카드의 강화 아이콘 수만큼 간접 피해를 입음.","star":true},{"id":"04065","name":"크로스본즈 갑옷","en":"* Crossbones' Armor","type":"attachment","enc":true,"set":"Crossbones","unique":true,"boost":3,"plus":{"atk":1,"sch":1},"tr":["ARMOR"],"traits":["갑옷"],"text":"크로스본즈에게 장착합니다.\n<b>강제 난입</b>: 크로스본즈가 피해를 입으려 할 때, 대신 그 피해를 이 카드에 놓습니다. 이 카드에 피해가 5 이상 있다면, 크로스본즈 갑옷을 버립니다."},{"id":"04066","name":"하이드라 폭격수","en":"Hydra Bomber","type":"minion","enc":true,"set":"Bomb Scare","unique":false,"hp":2,"atk":1,"sch":1,"boost":1,"tr":["HYDRA"],"traits":["하이드라"],"text":"<b>공개될 때</b>: 피해 2점을 입거나 주요 음모에 위협을 1만큼 놓는 것 중 하나를 선택합니다.","link":"01110"},{"id":"04067","name":"완전 자동 사격","en":"Full Auto","type":"treachery","enc":true,"set":"Crossbones","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 쇄도.\n<b>공개될 때(히어로)</b>: 조우 덱 맨 위에서 카드 X장을 버립니다. X는 크로스본즈의 공격과 같습니다. 이렇게 버려진 강화 아이콘마다 간접 피해 1점을 입습니다."},{"id":"04068","name":"무쇠처럼 단단한","en":"Hard as Nails","type":"treachery","enc":true,"set":"Crossbones","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 빌런에게 강인함 상태 카드를 줍니다. 그럴 수 없다면, 대신 빌런의 피해 3점을 치료합니다.\n<hr />\n[star] <b>강화</b>: 빌런에게 강인함 상태 카드를 줍니다. 그럴 수 없다면, 대신 빌런의 피해 3점을 치료합니다.","star":true,"boostStar":true},{"id":"04069","name":"무기고 습격","en":"Raid the Armory","type":"treachery","enc":true,"set":"Crossbones","unique":false,"boost":1,"tr":[],"incite":1,"traits":[],"text":"진척 1. <i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다.)</i>\n<b>공개될 때</b>: [[무기]] 장착 카드가 버려질 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 카드를 공개합니다."},{"id":"04070","name":"크로스본즈의 습격","en":"Crossbones' Assault","type":"side","enc":true,"set":"Crossbones","unique":false,"boost":2,"start":2,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 크로스본즈가 이 음모를 격파한 플레이어를 상대로 활성화합니다."},{"id":"04071","name":"궁지에 몰린 직원들","en":"Cornered Staff","type":"side","enc":true,"set":"Crossbones","unique":false,"boost":2,"start":3,"tr":[],"crisis":1,"traits":[],"text":"<b>공개될 때</b>: 조우 덱 맨 위에서 카드 1[per_hero]장을 버립니다. 이렇게 버려진 강화 아이콘마다 이 카드에 위협을 1만큼 추가로 놓습니다."},{"id":"04072","name":"레이저 소총","en":"Laser Rifle","type":"attachment","enc":true,"set":"Experimental Weapons","unique":false,"boost":2,"plus":{"atk":1},"tr":["EXPERIMENTAL","WEAPON"],"traits":["실험","무기"],"text":"빌런에게 장착합니다.\n[star] <b>강제 난입</b>: 장착된 빌런이 공격할 때, 그 공격은 원거리를 얻습니다.\n<b>히어로 행동</b>: [energy][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"04073","name":"에너지 방패","en":"Energy Shield","type":"attachment","enc":true,"set":"Experimental Weapons","unique":false,"boost":2,"tr":["EXPERIMENTAL","WEAPON"],"traits":["실험","무기"],"text":"빌런에게 장착합니다.\n장착된 빌런은 반격 1을 얻습니다.\n<b>히어로 행동</b>: [energy][mental] 자원을 소모 → 이 카드를 버림."},{"id":"04074","name":"파워 건틀렛","en":"Power Gauntlets","type":"attachment","enc":true,"set":"Experimental Weapons","unique":false,"boost":2,"plus":{"atk":0},"tr":["EXPERIMENTAL","WEAPON"],"traits":["실험","무기"],"text":"빌런에게 장착합니다.\n[star] <b>강제 반응</b>: 장착된 빌런이 당신을 공격해 피해를 입힌 후, 당신의 손에서 카드 1장을 버립니다.\n<b>히어로 행동</b>: [mental][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"04075","name":"외골격 슈트","en":"Exo-Suit","type":"attachment","enc":true,"set":"Experimental Weapons","unique":false,"boost":2,"plus":{"atk":1,"sch":1},"tr":["EXPERIMENTAL","WEAPON"],"traits":["실험","무기"],"text":"빌런에게 장착합니다.\n<b>히어로 행동</b>: [energy][mental][physical] 자원을 소모 → 이 카드를 버림."},{"id":"04076","name":"업소빙맨","en":"* Absorbing Man","type":"villain","enc":true,"set":"Absorbing Man","unique":true,"hp":14,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["BRUTE"],"traits":["야만"],"text":"업소빙맨은 플레이 영역에 있는 각 환경 카드의 특성을 얻습니다."},{"id":"04077","name":"업소빙맨","en":"* Absorbing Man","type":"villain","enc":true,"set":"Absorbing Man","unique":true,"hp":15,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["BRUTE"],"traits":["야만"],"text":"업소빙맨은 플레이 영역에 있는 각 환경 카드의 특성을 얻습니다.\n<b>공개될 때</b>: 초흡수 능력이 플레이 영역에 있다면, 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다. 그렇지 않다면, 조우 덱과 버린 조우 더미에서 초흡수 능력을 찾아 공개합니다. 이렇게 조우 덱을 찾았다면 조우 덱을 섞습니다."},{"id":"04078","name":"업소빙맨","en":"* Absorbing Man","type":"villain","enc":true,"set":"Absorbing Man","unique":true,"hp":16,"hpStar":true,"atk":3,"sch":2,"stage":3,"tr":["BRUTE"],"traits":["야만"],"text":"업소빙맨은 플레이 영역에 있는 각 환경 카드의 특성을 얻습니다.\n[star] <b>강제 반응</b>: 업소빙맨이 당신을 상대로 활성화한 후, 그가 다음 특성을 가지고 있다면:\n• [[얼음]] 또는 [[돌]] 특성: 주요 음모에 위협을 1만큼 놓습니다.\n• [[금속]] 또는 [[나무]] 특성: 간접 피해 1점을 입습니다.","star":true},{"id":"04079a","name":"아무도 지나갈 수 없다","en":"None Shall Pass","type":"main","enc":true,"set":"Absorbing Man","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 업소빙맨 (I), 업소빙맨 (II). 업소빙맨, 일반 조우 세트. 모듈식 조우 세트 1개 <i>(하이드라 순찰대).</i>\n<b>사전 준비</b>: 환경 카드가 버려질 때까지 조우 덱에서 카드를 버립니다. 그 카드를 플레이 영역에 놓고 버린 조우 더미를 조우 덱에 섞어 넣습니다."},{"id":"04079b","name":"아무도 지나갈 수 없다","en":"None Shall Pass","type":"main","enc":true,"set":"Absorbing Man","unique":false,"start":2,"startStar":true,"target":12,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 이 카드에 지연 카운터를 1만큼 놓습니다.\n<b>강제 난입</b>: 환경 카드가 플레이 영역에 들어올 때, 플레이 영역에 있는 다른 환경 카드를 모두 버립니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"04080","name":"울창한 숲","en":"Dense Forest","type":"environment","enc":true,"set":"Absorbing Man","unique":false,"surge":1,"tr":["WOOD"],"traits":["나무"],"text":"쇄도.\n<b>강제 반응</b>: 업소빙맨이 당신을 상대로 방어받지 않은 공격을 한 후, 간접 피해 1점을 입습니다(주요 음모에 지연 카운터가 5 이상 있다면 대신 간접 피해 2점).\n<hr />\n[star] <b>강화</b>: 이 카드를 플레이 영역에 놓습니다.","star":true,"boostStar":true},{"id":"04081","name":"눈 덮인 산비탈","en":"Snowy Hillside","type":"environment","enc":true,"set":"Absorbing Man","unique":false,"surge":1,"tr":["ICE"],"traits":["얼음"],"text":"쇄도.\n<b>강제 반응</b>: 업소빙맨이 당신을 상대로 방어받지 않은 공격을 한 후, 주요 음모에 위협을 1만큼 놓습니다(주요 음모에 지연 카운터가 5 이상 있다면 대신 위협을 2만큼).\n<hr />\n[star] <b>강화</b>: 이 카드를 플레이 영역에 놓습니다.","star":true,"boostStar":true},{"id":"04082","name":"돌출된 바위","en":"Rocky Outcrop","type":"environment","enc":true,"set":"Absorbing Man","unique":false,"surge":1,"tr":["STONE"],"traits":["돌"],"text":"쇄도.\n<b>강제 반응</b>: 업소빙맨이 당신을 상대로 방어받지 않은 공격을 한 후, 그의 피해 1점을 치료합니다(주요 음모에 지연 카운터가 5 이상 있다면 대신 피해 2점).\n<hr />\n[star] <b>강화</b>: 이 카드를 플레이 영역에 놓습니다.","star":true,"boostStar":true},{"id":"04083","name":"버려진 시설","en":"Abandoned Facility","type":"environment","enc":true,"set":"Absorbing Man","unique":false,"surge":1,"tr":["METAL"],"traits":["금속"],"text":"쇄도.\n<b>강제 반응</b>: 업소빙맨이 당신을 상대로 방어받지 않은 공격을 한 후, 당신의 손에서 자원 아이콘 1개를 버립니다(주요 음모에 지연 카운터가 5 이상 있다면 대신 자원 2개).\n<hr />\n[star] <b>강화</b>: 이 카드를 플레이 영역에 놓습니다.","star":true,"boostStar":true},{"id":"04084","name":"쇠공과 쇠사슬","en":"* Ball and Chain","type":"attachment","enc":true,"set":"Absorbing Man","unique":true,"plus":{"atk":1,"sch":1},"tr":["WEAPON"],"traits":["무기"],"text":"업소빙맨에게 장착합니다.\n<b>히어로 행동</b>: [physical] 자원을 소모 → 이 카드를 조우 덱에 섞어 넣음.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"04085","name":"지연 전술","en":"Stall Tactics","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 주요 음모에 있는 지연 카운터 2개마다 주요 음모에 위협을 1만큼 놓습니다. 이렇게 놓인 위협이 없다면, 이 카드는 쇄도를 얻습니다.\n<hr />\n[star] <b>강화</b>: 주요 음모에 지연 카운터가 5 이상 있다면, 간접 피해 1점을 입습니다.","star":true,"boostStar":true},{"id":"04086","name":"휘두르는 돌덩이","en":"Swinging Stone","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 업소빙맨이 암약합니다. 업소빙맨이 [[돌]] 특성을 가지고 있다면, 그는 이번 활성화 동안 음모 +1을 받습니다.\n<b>공개될 때(히어로)</b>: 업소빙맨이 당신을 공격합니다. 업소빙맨이 [[돌]] 특성을 가지고 있다면, 그는 이번 활성화 동안 공격 +1을 받습니다."},{"id":"04087","name":"강철 발차기","en":"Steel Kick","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 주요 음모에 위협을 2만큼 놓습니다(업소빙맨이 [[금속]] 특성을 가지고 있다면 대신 위협을 3만큼.)\n<b>공개될 때(히어로)</b>: 간접 피해 3점을 입습니다(업소빙맨이 [[금속]] 특성을 가지고 있다면 대신 간접 피해 4점.)"},{"id":"04088","name":"꿰뚫는 가시","en":"Piercing Thorns","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신의 손에서 무작위로 카드 1장을 버립니다. 업소빙맨이 [[나무]] 특성을 가지고 있다면, 당신이 조종하는 카드 1장을 버립니다.\n<hr />\n[star] <b>강화</b>: 업소빙맨이 [[돌]] 또는 [[나무]] 특성을 가지고 있다면, 당신은 기절합니다.","star":true,"boostStar":true},{"id":"04089","name":"옴니모프 복제","en":"Omni-Morph Duplication","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 업소빙맨이 다음 특성을 가지고 있다면:\n- [[얼음]] 특성: 당신의 아이덴티티를 소진합니다.\n- [[금속]] 특성: 업소빙맨에게 강인함 상태 카드를 주고 그의 피해 1점을 치료합니다.\n- [[돌]] 특성: 업소빙맨에게 강화 카드 1장을 뒷면으로 줍니다.\n- [[나무]] 특성: 당신의 손에서 무작위로 카드 1장을 버립니다."},{"id":"04090","name":"얼음 손아귀","en":"Icy Grip","type":"treachery","enc":true,"set":"Absorbing Man","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 당신은 기절합니다. 업소빙맨이 [[얼음]] 특성을 가지고 있다면, 간접 피해 2점을 입습니다.\n<hr />\n[star] <b>강화</b>: 업소빙맨이 [[얼음]] 또는 [[금속]] 특성을 가지고 있다면, 그에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"04091","name":"눈사태!","en":"Avalanche!","type":"side","enc":true,"set":"Absorbing Man","unique":false,"boost":3,"start":2,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 [energy] 자원 1개를 소모하거나 간접 피해 2점을 입는 것 중 하나를 선택해야 합니다(주요 음모에 지연 카운터가 5 이상 있다면 대신 간접 피해 3점.)"},{"id":"04092","name":"초흡수 능력","en":"Super Absorbing Power","type":"side","enc":true,"set":"Absorbing Man","unique":false,"start":3,"startStar":true,"tr":[],"traits":[],"text":"업소빙맨은 [[얼음]], [[금속]], [[돌]], [[나무]] 특성을 얻습니다.\n<hr />\n[star] <b>강화</b>: 이 카드를 공개합니다.","star":true,"boostStar":true},{"id":"04093","name":"태스크마스터","en":"* Taskmaster","type":"villain","enc":true,"set":"Taskmaster","unique":true,"hp":13,"hpStar":true,"atk":2,"sch":1,"stage":1,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"<b>강제 반응</b>: 플레이어가 히어로 형태로 변신한 후, 그 플레이어는 조우 덱 맨 위 카드를 버리고 그 카드의 강화 아이콘 수만큼 피해를 입습니다."},{"id":"04094","name":"태스크마스터","en":"* Taskmaster","type":"villain","enc":true,"set":"Taskmaster","unique":true,"hp":16,"hpStar":true,"atk":2,"sch":2,"stage":2,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"<b>공개될 때</b>: 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다.\n<b>강제 반응</b>: 플레이어가 히어로 형태로 변신한 후, 그 플레이어는 조우 덱 맨 위 카드를 버리고 그 카드의 강화 아이콘 수만큼 피해를 입습니다."},{"id":"04095","name":"태스크마스터","en":"* Taskmaster","type":"villain","enc":true,"set":"Taskmaster","unique":true,"hp":17,"hpStar":true,"atk":3,"sch":3,"stage":3,"tr":["HYDRA","MERCENARY"],"traits":["하이드라","용병"],"text":"<b>공개될 때</b>: 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다.\n<b>강제 반응</b>: 플레이어가 히어로 형태로 변신한 후, 그 플레이어는 조우 덱 맨 위 카드를 버리고 그 카드의 강화 아이콘 수만큼 피해를 입습니다."},{"id":"04096a","name":"히어로 사냥","en":"Hunting Down Heroes","type":"main","enc":true,"set":"Taskmaster","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 태스크마스터 (I), 태스크마스터 (II). 태스크마스터, 하이드라 순찰대, 일반 조우 세트. 모듈식 조우 세트 1개 <i>(무기의 달인).</i>\n<b>사전 준비</b>: 각 [[포로]] 동료를 게임 밖에 따로 놓아둡니다. 조우 덱에서 하이드라 순찰대를 찾아 플레이 영역에 놓습니다. 조우 덱을 섞습니다."},{"id":"04096b","name":"히어로 사냥","en":"Hunting Down Heroes","type":"main","enc":true,"set":"Taskmaster","unique":false,"start":1,"startStar":true,"target":12,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 히어로 형태인 각 플레이어는 이 카드에 위협을 1만큼 놓거나 피해 1점을 입는 것 중 하나를 선택해야 합니다.\n<b>이 스테이지가 완료되면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"04097","name":"문 나이트","en":"* Moon Knight","type":"ally","enc":false,"sub":"마크 스펙터","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":0,"res":"G","cls":"Encounter","tr":["CAPTIVE","HERO FOR HIRE"],"traits":["포로","용병 히어로"],"text":"<b>반응</b>: 당신이 손에서 문 나이트를 플레이한 후, [wild] 자원 1개를 소모 → 카드 2장을 뽑음."},{"id":"04098","name":"샹치","en":"* Shang-Chi","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":2,"thwStar":true,"cost":0,"res":"G","cls":"Encounter","tr":["CAPTIVE","HERO FOR HIRE"],"traits":["포로","용병 히어로"],"text":"<b>반응</b>: 당신이 손에서 샹치를 플레이한 후, [energy] 자원 1개를 소모 → 적 하나를 기절시킴."},{"id":"04099","name":"화이트 타이거","en":"* White Tiger","type":"ally","enc":false,"sub":"앤젤라 델 토로","unique":true,"hp":3,"atk":1,"atkStar":true,"thw":3,"thwStar":true,"cost":0,"res":"G","cls":"Encounter","tr":["CAPTIVE","HERO FOR HIRE"],"traits":["포로","용병 히어로"],"text":"<b>반응</b>: 당신이 손에서 화이트 타이거를 플레이한 후, [mental] 자원을 소모 → 음모 하나에서 위협을 3만큼 제거함."},{"id":"04100","name":"엘렉트라","en":"* Elektra","type":"ally","enc":false,"unique":true,"hp":3,"atk":3,"atkStar":true,"thw":1,"thwStar":true,"cost":0,"res":"G","cls":"Encounter","tr":["CAPTIVE","HERO FOR HIRE"],"traits":["포로","용병 히어로"],"text":"<b>반응</b>: 당신이 손에서 엘렉트라를 플레이한 후, [physical] 자원 1개를 소모 → 적 하나에게 피해 3점을 입힘."},{"id":"04101","name":"하이드라 사냥꾼","en":"Hydra Hunter","type":"minion","enc":true,"set":"Taskmaster","unique":false,"hp":3,"atk":2,"sch":2,"tr":["HYDRA"],"traits":["하이드라"],"text":"[star] 하이드라 사냥꾼의 공격은 관통과 원거리를 얻습니다.\n<hr />\n[star] <b>강화</b>: 당신이 히어로 형태라면, 피해 1점을 입습니다. 그렇지 않다면 주요 음모에 위협을 1만큼 놓습니다.","star":true,"boostStar":true},{"id":"04102","name":"태스크마스터의 검","en":"* Taskmaster's Sword","type":"attachment","enc":true,"set":"Taskmaster","unique":true,"boost":3,"plus":{"atk":1},"tr":["WEAPON"],"traits":["무기"],"text":"태스크마스터에게 장착합니다.\n[star] 태스크마스터의 공격은 관통을 얻습니다.\n<b>히어로 행동</b>: 당신의 히어로를 소진하고 [mental][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"04103","name":"태스크마스터의 방패","en":"* Taskmaster's Shield","type":"attachment","enc":true,"set":"Taskmaster","unique":true,"boost":3,"tr":["ARMOR","WEAPON"],"traits":["갑옷","무기"],"text":"태스크마스터에게 장착합니다.\n태스크마스터는 반격 1을 얻습니다.\n<b>히어로 행동</b>: 당신의 히어로를 소진하고 [mental][physical] 자원을 소모 → 이 카드를 버림."},{"id":"04104","name":"사진 같은 반사신경","en":"Photographic Reflexes","type":"attachment","enc":true,"set":"Taskmaster","unique":false,"boost":2,"tr":[],"traits":[],"text":"태스크마스터에게 장착합니다.\n<b>강제 난입</b>: 플레이어가 태스크마스터를 공격할 때, 태스크마스터에게 입혀질 모든 피해를 방지하고 대신 그만큼의 피해를 그 플레이어의 아이덴티티에게 입힙니다. 그러고 나서, 사진 같은 반사신경을 버립니다. (공격마다 최대 1회.)"},{"id":"04105","name":"모방","en":"Mimicry","type":"treachery","enc":true,"set":"Taskmaster","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 당신의 덱 맨 위에서 카드 5장을 버립니다. 이렇게 [[저지]] 카드가 버려졌다면, 태스크마스터가 암약합니다.\n<b>공개될 때(히어로)</b>: 당신의 덱 맨 위에서 카드 5장을 버립니다. 이렇게 [[공격]] 카드가 버려졌다면, 태스크마스터가 당신을 공격합니다."},{"id":"04106","name":"하이드라의 추적","en":"Hunted by Hydra","type":"treachery","enc":true,"set":"Taskmaster","unique":false,"boost":1,"tr":[],"incite":1,"traits":[],"text":"진척 1. <i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다.)</i>\n<b>공개될 때</b>: 히어로 형태인 각 플레이어는 피해 1점을 입고 자신의 손에서 무작위로 카드 1장을 버립니다."},{"id":"04107","name":"하이드라에게 붙잡힘","en":"Captured by Hydra","type":"side","enc":true,"set":"Taskmaster","unique":false,"boost":2,"start":5,"accel":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 따로 놓아둔 [[포로]] 동료 하나를 무작위로 골라 이 음모 아래에 뒷면으로 놓습니다. 이 음모가 격파되면, 이 음모를 격파한 플레이어는 그 동료를 자신의 손으로 가져오고 이 음모를 게임에서 제거합니다."},{"id":"04108","name":"태스크마스터의 훈련소","en":"Taskmaster's Training Camp","type":"side","enc":true,"set":"Taskmaster","unique":false,"boost":3,"start":2,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 하수인이 플레이 영역에 들어온 후, 그 하수인에게 강인함 상태 카드를 줍니다."},{"id":"04109","name":"졸라","en":"* Zola","type":"villain","enc":true,"set":"Zola","unique":true,"hp":12,"hpStar":true,"atk":1,"sch":2,"stage":1,"retaliate":1,"tr":["ANDROID","HYDRA"],"traits":["안드로이드","하이드라"],"text":"반격 1."},{"id":"04110","name":"졸라","en":"* Zola","type":"villain","enc":true,"set":"Zola","unique":true,"hp":14,"hpStar":true,"atk":2,"sch":2,"stage":2,"retaliate":1,"tr":["ANDROID","HYDRA"],"traits":["안드로이드","하이드라"],"text":"반격 1.\n<b>공개될 때</b>: 조우 덱과 버린 조우 더미에서 실험 대상 부가 음모를 찾아 공개합니다.\n(조우 덱을 섞습니다.)"},{"id":"04111","name":"졸라","en":"* Zola","type":"villain","enc":true,"set":"Zola","unique":true,"hp":16,"hpStar":true,"atk":2,"sch":3,"stage":3,"retaliate":1,"tr":["ANDROID","HYDRA"],"traits":["안드로이드","하이드라"],"text":"반격 1.\n<b>공개될 때</b>: 각 플레이어는 조우 덱과 버린 조우 더미에서 하수인 하나를 찾아 공개합니다. (조우 덱을 섞습니다.)"},{"id":"04112a","name":"닥터 졸라의 섬","en":"The Island of Dr. Zola","type":"main","enc":true,"set":"Zola","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 졸라 (I), 졸라 (II). 졸라, 일반 조우 세트. 모듈식 조우 세트 1개 <i>(습격받는 중)</i>\n<b>사전 준비</b>: 조우 덱에서 하이드라 감옥을 찾아 공개합니다. 각 플레이어는 조우 덱에서 궁극의 바이오 서번트 한 장을 찾아 자신과 교전 중인 채로 플레이 영역에 놓습니다. 조우 덱을 섞습니다."},{"id":"04112b","name":"닥터 졸라의 섬","en":"The Island of Dr. Zola","type":"main","enc":true,"set":"Zola","unique":false,"start":0,"target":6,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 이 카드에 실험 카운터를 1만큼 놓습니다. 그러고 나서, 이 카드에 실험 카운터가 3 이상 있다면, 하수인이 버려질 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 하수인을 시작 플레이어와 교전 중인 채로 플레이 영역에 놓고 이 음모에서 실험 카운터를 3만큼 제거합니다.","star":true},{"id":"04113a","name":"미치광이 박사","en":"The Mad Doctor","type":"main","enc":true,"set":"Zola","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 조우 덱과 버린 조우 더미에서 하수인 하나를 찾아 공개합니다. 조우 덱을 섞습니다."},{"id":"04113b","name":"미치광이 박사","en":"The Mad Doctor","type":"main","enc":true,"set":"Zola","unique":false,"start":1,"startStar":true,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 이 카드에 실험 카운터를 1만큼 놓습니다. 그러고 나서, 이 카드에 실험 카운터가 3 이상 있다면, 하수인이 버려질 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 하수인을 시작 플레이어와 교전 중인 채로 플레이 영역에 놓고 이 음모에서 실험 카운터를 3만큼 제거합니다.\n<b>이 음모가 완료되면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"04114","name":"궁극의 바이오 서번트","en":"Ultimate Bio-Servant","type":"minion","enc":true,"set":"Zola","unique":false,"hp":4,"atk":1,"sch":1,"tr":["HYDRA","MUTATE"],"toughness":1,"traits":["하이드라","변이체"],"text":"강인.\n[star] 궁극의 바이오 서번트는 자신에게 장착된 장착 카드마다 공격 +1을 받습니다.\n<hr />\n[star] <b>강화</b>: 빌런에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"04115","name":"졸라의 변이체","en":"Zola's Mutate","type":"minion","enc":true,"set":"Zola","unique":false,"hp":5,"atk":2,"sch":1,"tr":["HYDRA","MUTATE"],"traits":["하이드라","변이체"],"text":"<b>공개될 때</b>: [[과학]] 장착 카드가 버려질 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 카드를 졸라의 변이체에게 장착합니다.\n<hr />\n[star] <b>강화</b>: 졸라의 변이체를 조우 덱에 섞어 넣습니다.","star":true,"boostStar":true},{"id":"04116","name":"광폭한 변이체","en":"Berserk Mutate","type":"minion","enc":true,"set":"Zola","unique":false,"hp":3,"atk":2,"sch":0,"tr":["HYDRA","MUTATE"],"quickstrike":1,"traits":["하이드라","변이체"],"text":"속공.\n<hr />\n[star] <b>강화</b>: 주요 음모에 실험 카운터를 1만큼 놓습니다. 주요 음모에 있는 실험 카운터마다, 졸라는 이번 활성화 동안 음모 +1과 공격 +1을 받습니다.","star":true,"boostStar":true},{"id":"04117","name":"방어 프로그래밍","en":"Defensive Programming","type":"attachment","enc":true,"set":"Zola","unique":false,"boost":1,"tr":["TECH"],"traits":["과학"],"text":"다른 방어 프로그래밍이 장착되지 않은 하수인 중 남은 생명력이 가장 많은 하수인에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n장착된 하수인은 생명력 +2를 받고 경호를 얻습니다."},{"id":"04118","name":"통증 억제제","en":"Pain Inhibitors","type":"attachment","enc":true,"set":"Zola","unique":false,"boost":1,"tr":["TECH"],"traits":["과학"],"text":"다른 통증 억제제가 장착되지 않은 하수인 중 남은 생명력이 가장 많은 하수인에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n장착된 하수인은 생명력 +2를 받고 반격 1을 얻습니다."},{"id":"04119","name":"신경 임플란트","en":"Neurological Implants","type":"attachment","enc":true,"set":"Zola","unique":false,"boost":1,"plus":{"atk":2,"sch":2},"tr":["TECH"],"traits":["과학"],"text":"다른 신경 임플란트가 장착되지 않은 하수인 중 남은 생명력이 가장 많은 하수인에게 장착합니다. 그럴 수 없다면, 이 카드는 쇄도를 얻습니다.\n장착된 하수인은 생명력 +2를 받습니다."},{"id":"04120","name":"정신 광선","en":"Mind Ray","type":"treachery","enc":true,"set":"Zola","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 졸라가 암약합니다. 당신은 혼란에 빠집니다.\n<b>공개될 때(히어로)</b>: 졸라가 당신을 공격합니다. 당신은 기절합니다."},{"id":"04121","name":"기술 강화","en":"Technological Enhancements","type":"treachery","enc":true,"set":"Zola","unique":false,"tr":[],"incite":1,"traits":[],"text":"진척 1.\n<b>공개될 때</b>: 주요 음모에 실험 카운터를 1만큼 놓습니다.\n<hr />\n[star] <b>강화</b>: 주요 음모에 실험 카운터를 1만큼 놓습니다.","star":true,"boostStar":true},{"id":"04122","name":"하이드라 감옥","en":"Hydra Prison","type":"side","enc":true,"set":"Zola","unique":false,"start":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 자신의 덱, 버린 더미, 손에서 히어로 전용 동료 하나를 찾아 이 음모 아래에 뒷면으로 놓습니다. 이 음모에 위협을 X만큼 놓습니다. X는 이 음모 아래에 있는 모든 동료의 비용 합계입니다. 각 플레이어는 자신의 덱을 섞습니다.\n<b>격파될 때</b>: 이 음모를 게임에서 제거하고 그 아래에 있는 각 동료를 소유자의 손으로 되돌립니다."},{"id":"04123","name":"실험 대상","en":"Test Subjects","type":"side","enc":true,"set":"Zola","unique":false,"boost":2,"start":2,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 시작 플레이어는 하수인이 버려질 때까지 조우 덱 맨 위에서 카드를 버립니다. 그 하수인을 공개합니다."},{"id":"04124","name":"졸라의 실험","en":"Zola's Experiments","type":"side","enc":true,"set":"Zola","unique":false,"boost":3,"start":3,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>강제 반응</b>: 하수인이 플레이 영역에 들어온 후, 버린 조우 더미에서 가장 위에 있는 [[과학]] 장착 카드를 그 하수인에게 장착합니다."},{"id":"04125","name":"레드 스컬","en":"* Red Skull","type":"villain","enc":true,"set":"Red Skull","unique":true,"hp":12,"hpStar":true,"atk":0,"sch":2,"stage":1,"tr":["HYDRA"],"traits":["하이드라"],"text":"[star] 레드 스컬은 플레이 영역에 있는 부가 음모마다 공격 +1을 받습니다.","star":true},{"id":"04126","name":"레드 스컬","en":"* Red Skull","type":"villain","enc":true,"set":"Red Skull","unique":true,"hp":16,"hpStar":true,"atk":1,"sch":3,"stage":2,"tr":["HYDRA"],"traits":["하이드라"],"text":"[star] 레드 스컬은 플레이 영역에 있는 부가 음모마다 공격 +1을 받습니다.\n<b>공개될 때</b>: 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다.","star":true},{"id":"04127","name":"레드 스컬","en":"* Red Skull","type":"villain","enc":true,"set":"Red Skull","unique":true,"hp":20,"hpStar":true,"atk":2,"sch":3,"stage":3,"tr":["HYDRA"],"traits":["하이드라"],"text":"[star] 레드 스컬은 플레이 영역에 있는 부가 음모마다 공격 +1을 받습니다.\n<b>공개될 때</b>: 각 플레이어에게 조우 카드를 1장씩 나누어 줍니다.","star":true},{"id":"04128a","name":"레드 스컬의 부상","en":"The Rise of Red Skull","type":"main","enc":true,"set":"Red Skull","unique":false,"stage":1,"tr":[],"traits":[],"text":"<b>구성</b>: 레드 스컬 (I), 레드 스컬 (II). 레드 스컬 및 일반 조우 세트. 모듈식 조우 세트 2개 <i>(하이드라 맹공, 하이드라 순찰대).</i>\n<b>사전 준비</b>: 레드 하우스를 플레이 영역에 내려놓습니다. 다른 모든 부가 음모를 부가 음모 덱에 섞어 넣고 그 덱을 조우 덱 옆에 놓습니다(부록 참조).\n슬리퍼를 플레이 영역 밖에 따로 놓아둡니다."},{"id":"04128b","name":"레드 스컬의 부상","en":"The Rise of Red Skull","type":"main","enc":true,"set":"Red Skull","unique":false,"start":0,"target":8,"targetStar":true,"esc":1,"escStar":true,"stage":1,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 부가 음모 덱 맨 위 카드를 공개하고 플레이 영역에 내려놓습니다.","star":true},{"id":"04129a","name":"신세계 하이드라","en":"New World Hydra","type":"main","enc":true,"set":"Red Skull","unique":false,"stage":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 부가 음모 덱 맨 위 카드를 공개하고 플레이 영역에 내려놓습니다."},{"id":"04129b","name":"신세계 하이드라","en":"New World Hydra","type":"main","enc":true,"set":"Red Skull","unique":false,"start":1,"startStar":true,"target":11,"targetStar":true,"esc":1,"escStar":true,"stage":2,"tr":[],"traits":[],"text":"[star] <b>강제 반응</b>: 빌런 페이즈의 1단계를 해결한 후, 부가 음모 덱 맨 위 카드를 공개하고 플레이 영역에 내려놓습니다.\n<b>이 음모가 완료되면, 플레이어들은 게임에서 패배합니다.</b>","star":true},{"id":"04130","name":"슬리퍼","en":"* The Sleeper","type":"minion","enc":true,"set":"Red Skull","unique":true,"hp":5,"hpStar":true,"atk":3,"sch":1,"boost":1,"retaliate":1,"tr":["ELITE","HYDRA","ROBOT"],"guard":1,"toughness":1,"traits":["간부","하이드라","로봇"],"text":"경호. 반격 1. 강인.\n<b>공개될 때</b>: 슬리퍼가 시작 플레이어와 교전합니다.\n<b>격파될 때</b>: 슬리퍼를 게임에서 제거합니다."},{"id":"04131","name":"하이드라 외골격 군인","en":"Hydra Exo-Soldier","type":"minion","enc":true,"set":"Red Skull","unique":false,"hp":5,"atk":2,"sch":2,"tr":["HYDRA"],"toughness":1,"traits":["하이드라"],"text":"강인.\n<hr />\n[star] <b>강화</b>: 빌런에게 강인함 상태 카드와 강화 카드 1장을 추가로 줍니다.","star":true,"boostStar":true},{"id":"04132","name":"레드 스컬의 루거","en":"* Red Skull's Luger","type":"attachment","enc":true,"set":"Red Skull","unique":true,"plus":{"atk":1,"sch":1},"tr":["WEAPON"],"traits":["무기"],"text":"레드 스컬에게 장착합니다.\n[star] 레드 스컬의 공격은 관통과 원거리를 얻습니다.\n<b>히어로 행동</b>: [energy] [mental] [physical] 자원을 소모 → 이 카드를 버림.\n<hr />\n[star] <b>강화</b>: 레드 스컬에게 장착합니다.","star":true,"boostStar":true},{"id":"04133","name":"레드 스컬의 라이트 훅","en":"Red Skull's Right Hook","type":"attachment","enc":true,"set":"Red Skull","unique":false,"boost":3,"tr":["SKILL"],"traits":["기술"],"text":"레드 스컬에게 장착합니다.\n레드 스컬은 반격 1을 얻습니다.\n<b>히어로 행동</b>: [energy][mental][physical] 자원을 소모 → 이 카드를 버림."},{"id":"04134","name":"전략의 대가","en":"Master Strategist","type":"attachment","enc":true,"set":"Red Skull","unique":false,"boost":2,"tr":["SKILL"],"traits":["기술"],"text":"레드 스컬에게 장착합니다.\n[star] <b>강제 난입</b>: 레드 스컬이 활성화할 때, 플레이 영역에 있는 부가 음모마다 그에게 강화 카드 1장을 추가로 줍니다. 그러고 나서 이 카드를 버립니다. (활성화마다 최대 1회.)","star":true},{"id":"04135","name":"뒤틀린 현실","en":"Twisted Reality","type":"attachment","enc":true,"set":"Red Skull","unique":false,"boost":2,"tr":["CONDITION"],"incite":1,"traits":["상태"],"text":"진척 1.\n부가 음모에 장착합니다.\n<b>강제 난입</b>: 장착된 부가 음모가 격파될 때, 시작 플레이어에게 조우 카드를 1장 나누어 줍니다."},{"id":"04136","name":"앙숙","en":"Bitter Rival","type":"treachery","enc":true,"set":"Red Skull","unique":false,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 부가 음모마다 당신이 조종하는 캐릭터 하나를 소진합니다.\n<hr />\n[star] <b>강화</b>: 당신이 조종하는 캐릭터 하나를 소진합니다.","star":true,"boostStar":true},{"id":"04137","name":"거짓 퍼뜨리기","en":"Spreading Lies","type":"treachery","enc":true,"set":"Red Skull","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 플레이 영역에 있는 각 음모에 위협을 2만큼 놓습니다.\n<hr />\n[star] <b>강화</b>: 레드 스컬에게 강인함 상태 카드를 줍니다.","star":true,"boostStar":true},{"id":"04138","name":"무한한 힘","en":"Infinite Power","type":"treachery","enc":true,"set":"Red Skull","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때 (일상)</b>: 레드 스컬에게 강인함 상태 카드를 줍니다. 레드 스컬이 암약합니다.\n<b>공개될 때 (히어로)</b>: 레드 스컬에게 강인함 상태 카드를 줍니다. 레드 스컬이 당신을 공격합니다."},{"id":"04139","name":"레드 하우스","en":"The Red House","type":"side","enc":true,"set":"Red Skull","unique":false,"start":3,"startStar":true,"tr":[],"traits":[],"text":"레드 스컬은 피해를 입을 수 없습니다.\n<b>난입</b>: 캐릭터가 이 부가 음모를 저지할 때, 그 캐릭터는 저지 수치 대신 공격 수치를 사용해도 됩니다."},{"id":"04140","name":"깨어난 슬리퍼","en":"The Sleeper Awakened","type":"side","enc":true,"set":"Red Skull","unique":false,"start":0,"tr":[],"traits":[],"text":"슬리퍼가 플레이 영역에 있는 동안, 이 음모는 플레이 영역을 떠날 수 없습니다.\n<b>공개될 때</b>: 슬리퍼를 시작 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다. 슬리퍼가 격파될 때, 이 카드를 게임에서 제거합니다."},{"id":"04141","name":"포로 수용소","en":"Prison Camps","type":"side","enc":true,"set":"Red Skull","unique":false,"start":3,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 이 음모를 격파한 플레이어는 자신의 덱과 버린 더미에서 동료 하나를 찾아 플레이 영역에 내려놓고, 자신의 덱을 섞습니다."},{"id":"04142","name":"과거 검열","en":"Censor the Past","type":"side","enc":true,"set":"Red Skull","unique":false,"start":3,"startStar":true,"accel":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 각 플레이어는 자신의 버린 더미에서 카드를 3장까지 선택해 자신의 덱에 섞어 넣습니다."},{"id":"04143","name":"하이드라 증원군","en":"Hydra Reinforcements","type":"side","enc":true,"set":"Red Skull","unique":false,"start":2,"startStar":true,"hazard":1,"tr":[],"traits":[],"text":"<b>격파될 때</b>: 이 음모를 격파한 플레이어는 <b>간부</b>가 아닌 하수인 1장을 버립니다."},{"id":"04144","name":"대혼란","en":"Mass Chaos","type":"side","enc":true,"set":"Red Skull","unique":false,"start":0,"tr":[],"crisis":1,"traits":[],"text":"<b>공개될 때</b>: 각 플레이어는 자신의 덱 맨 위에서 카드 5장을 버리고, 이렇게 버린 서로 다른 유형의 자원 아이콘([energy],[mental],[physical], 또는 [wild])마다 이 카드에 위협을 1만큼 놓습니다."},{"id":"04145","name":"하이드라 화염 군인","en":"Hydra Flame-Soldier","type":"minion","enc":true,"set":"Hydra Assault","unique":false,"hp":4,"atk":1,"sch":1,"tr":["HYDRA"],"traits":["하이드라"],"text":"[star] <b>강제 반응</b>: 하이드라 화염 군인이 당신에게 방어받지 않은 공격을 한 후, 당신이 조종하는 지원 1장을 버립니다.\n<hr />\n[star] <b>강화</b>: 이 카드가 방어받지 않은 공격 중에 해결된다면, 당신이 조종하는 지원 1장을 버립니다.","star":true,"boostStar":true},{"id":"04146","name":"하이드라 제트 병사","en":"Hydra Jet-Trooper","type":"minion","enc":true,"set":"Hydra Assault","unique":false,"hp":3,"atk":2,"sch":0,"tr":["HYDRA"],"quickstrike":1,"traits":["하이드라"],"text":"속공.\n<hr />\n[star] <b>강화</b>: 당신이 히어로 형태라면, 이 활성화 후에 빌런이 당신을 공격합니다. 그 공격에는 강화 카드를 나누어 주지 않습니다.","star":true,"boostStar":true},{"id":"04147","name":"헤일 하이드라!","en":"Hail Hydra!","type":"treachery","enc":true,"set":"Captain America Nemesis","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때</b>: 각 [[하이드라]] 하수인이 교전 중인 히어로를 공격합니다. 이렇게 공격받지 않은 각 플레이어는 조우 덱과 버린 조우 더미에서 [[하이드라]] 하수인 하나를 찾아 그 플레이어와 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 찾았다면, 조우 덱을 섞습니다.","link":"03030"},{"id":"04148","name":"전투용 나이프","en":"Combat Knife","type":"attachment","enc":true,"set":"Weapon Master","unique":false,"boost":1,"plus":{"atk":1},"tr":["WEAPON"],"traits":["무기"],"text":"빌런에게 장착합니다.\n[star] 장착된 빌런의 공격은 관통을 얻습니다.\n<b>히어로 행동</b>: [mental][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"04149","name":"하이드라 보조 화기","en":"Hydra Sidearm","type":"attachment","enc":true,"set":"Weapon Master","unique":false,"boost":2,"plus":{"atk":1},"tr":["WEAPON"],"traits":["무기"],"text":"빌런에게 장착합니다.\n[star] <b>강제 난입</b>: 장착된 빌런이 공격할 때, 그 공격은 원거리를 얻습니다.\n<b>히어로 행동</b>: [mental][physical] 자원을 소모 → 이 카드를 버림.","star":true},{"id":"04150","name":"무기의 달인","en":"Weapon Master","type":"treachery","enc":true,"set":"Weapon Master","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때 (일상)</b>: 빌런이 암약합니다. 빌런에게 [[무기]] 장착 카드가 있다면, 이 카드는 쇄도를 얻습니다.\n<b>공개될 때 (히어로)</b>: 빌런이 당신을 공격합니다. 빌런에게 [[무기]] 장착 카드가 있다면, 이 카드는 쇄도를 얻습니다."},{"id":"04151","name":"충격 수류탄","en":"Concussion Grenade","type":"treachery","enc":true,"set":"Weapon Master","unique":false,"boost":1,"tr":[],"traits":[],"text":"<b>공개될 때 (일상)</b>: 당신은 혼란에 빠집니다. 주요 음모에 위협을 1만큼 놓습니다(이미 혼란에 빠져 있었다면 대신 2만큼).\n<b>공개될 때 (히어로)</b>: 당신은 기절합니다. 당신의 히어로에게 피해 1점을 입힙니다(이미 기절해 있었다면 대신 2점)."},{"id":"04152","name":"하이드라 직업군인","en":"Hydra Regular","type":"minion","enc":true,"set":"Hydra Patrol","unique":false,"hp":2,"atk":2,"sch":1,"boost":2,"tr":["HYDRA"],"incite":1,"traits":["하이드라"],"text":"진척 1. <i>(이 카드가 공개되면, 주요 음모에 위협을 1만큼 놓습니다.)</i>"},{"id":"04153","name":"하이드라 군인","en":"Hydra Soldier","type":"minion","enc":true,"set":"Legions of Hydra","unique":false,"hp":4,"atk":2,"sch":1,"boost":1,"tr":["HYDRA"],"guard":1,"traits":["하이드라"],"text":"경호.<i>(이 하수인이 당신과 교전 중인 한, 당신은 빌런을 공격할 수 없습니다.)</i>\n<b>격파될 때</b>: 교전 중인 플레이어에게 조우 카드를 한 장 나누어 줍니다.","link":"01182"},{"id":"04154","name":"하이드라 순찰대","en":"Hydra Patrol","type":"side","enc":true,"set":"Hydra Patrol","unique":false,"boost":2,"start":2,"startStar":true,"tr":[],"crisis":1,"traits":[],"text":"<b>격파될 때</b>: 각 플레이어는 조우 덱과 버린 조우 더미에서 [[하이드라]] 하수인 하나를 찾아 자신과 교전 중인 채로 플레이 영역에 내려놓습니다. 조우 덱을 섞습니다."},{"id":"04155","name":"아드레날린 자극제","en":"Adrenal Stims","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"G","cls":"Campaign;Basic","tr":["TECH"],"setupCard":1,"traits":["과학"],"text":"사전 준비.\n<b>히어로 행동:</b> 이 카드를 버리고 캠페인 기록지에서 제거 → 당신의 히어로를 준비하고 당신의 히어로가 입은 피해 5점을 치료."},{"id":"04156","name":"전술 스캐너","en":"Tactical Scanner","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"G","cls":"Campaign;Basic","tr":["TECH"],"setupCard":1,"traits":["과학"],"text":"사전 준비.\n<b>히어로 행동:</b> 이 카드를 버리고 캠페인 기록지에서 제거 → 카드 5장을 뽑음."},{"id":"04157","name":"비상 순간이동 장치","en":"Emergency Teleporter","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"G","cls":"Campaign;Basic","tr":["TECH"],"setupCard":1,"traits":["과학"],"text":"사전 준비.\n<b>히어로 행동:</b> 이 카드를 버리고 캠페인 기록지에서 제거 → 당신의 덱과 버린 더미에서 동료 하나를 찾아 플레이 영역에 내려놓고 강인함 상태 카드를 줍니다."},{"id":"04158","name":"레이저 캐논","en":"Laser Cannon","type":"upgrade","enc":false,"unique":false,"cost":0,"res":"G","cls":"Campaign;Basic","tr":["TECH"],"setupCard":1,"traits":["과학"],"text":"사전 준비.\n<b>히어로 행동:</b> 이 카드를 버리고 캠페인 기록지에서 제거 → 당신과 교전 중인 각 하수인과 빌런에게 피해 5점을 입힘."},{"id":"04159a","name":"기본 저지 업그레이드","en":"Basic Thwart Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +2를 받습니다.\n당신의 히어로가 저지 +1을 받습니다."},{"id":"04159b","name":"향상된 저지 업그레이드","en":"Improved Thwart Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n 당신은 생명력 +2를 받습니다.\n당신의 히어로가 저지 +1을 받습니다.\n<b>반응:</b> 당신이 부가 음모를 격파한 후, 이 카드를 소진 → 카드 1장을 뽑음."},{"id":"04160a","name":"기본 공격 업그레이드","en":"Basic Attack Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +1을 받습니다.\n당신의 히어로가 공격 +1을 받습니다."},{"id":"04160b","name":"향상된 공격 업그레이드","en":"Improved Attack Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +1을 받습니다.\n당신의 히어로가 공격 +1을 받습니다.\n<b>히어로 반응:</b> 당신이 하수인을 격파한 후, 이 카드를 소진 → 카드 1장을 뽑음."},{"id":"04161a","name":"기본 방어 업그레이드","en":"Basic Defense Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +3을 받습니다.\n당신의 히어로가 방어 +1을 받습니다."},{"id":"04161b","name":"향상된 방어 업그레이드","en":"Improved Defense Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +3을 받습니다.\n당신의 히어로가 방어 +1을 받습니다.\n<b>히어로 반응:</b> 당신이 적의 공격을 방어한 후, 이 카드를 소진 → 카드 1장을 뽑음."},{"id":"04162a","name":"기본 회복 업그레이드","en":"Basic Recovery Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +4를 받습니다.\n당신의 일상은 회복 +1을 받습니다."},{"id":"04162b","name":"향상된 회복 업그레이드","en":"Improved Recovery Upgrade","type":"upgrade","enc":false,"unique":false,"cls":"Campaign;Basic","tr":["CONDITION"],"permanent":1,"setupCard":1,"traits":["상태"],"text":"영속. 사전 준비.\n당신은 생명력 +4를 받습니다.\n당신의 일상은 회복 +1을 받습니다.\n<b>반응:</b> 당신이 회복 기능을 사용한 후, 이 카드를 소진 → 카드 1장을 뽑음."},{"id":"04163","name":"졸라 알고리즘","en":"Zola's Algorithm","type":"obligation","enc":true,"set":"Expert Campaign","unique":false,"accel":1,"tr":[],"traits":[],"text":"<b>일상 행동</b> 당신의 일상을 소진하고 [mental] 자원을 소모 → 이 카드를 버림."},{"id":"04164","name":"의료 응급상황","en":"Medical Emergency","type":"obligation","enc":true,"set":"Expert Campaign","unique":false,"tr":[],"traits":[],"text":"<b>강제 반응:</b> 당신의 차례 끝에, 당신이 히어로 형태라면 피해 1점을 입습니다.\n<b>일상 행동:</b>당신의 덱 맨 위에서 카드 5장을 버리고 [physical] 자원을 소모 → 이 카드를 버림."},{"id":"04165","name":"계엄령","en":"Martial Law","type":"obligation","enc":true,"set":"Expert Campaign","unique":false,"tr":[],"traits":[],"text":"당신의 손 크기가 1만큼 감소합니다.\n<b>일상 행동:</b> 당신에게 조우 카드 1장을 나누어 주고 [energy] 자원을 소모 → 이 카드를 버림."},{"id":"04166","name":"안티 히어로 선전","en":"Anti-Hero Propaganda","type":"obligation","enc":true,"set":"Expert Campaign","unique":false,"tr":[],"traits":[],"text":"당신의 히어로는 저지 -1, 공격 -1, 방어 -1을 받습니다.\n<b>일상 행동:</b> 피해 2점을 입고 [wild] 자원을 소모 → 이 카드를 버림."}]});
